558	    private func donateSendMessageIntent() async {
559	        guard let displayName = roomProxy.details.name ?? roomProxy.details.canonicalAlias, !displayName.isEmpty else {
560	            MXLog.error("Failed donating send message intent, room missing name or alias.")
561	            return
562	        }
563	        
564	        let groupName = INSpeakableString(spokenPhrase: displayName)
565	        
566	        let sendMessageIntent = INSendMessageIntent(recipients: nil,
567	                                                    outgoingMessageType: .outgoingMessageText,
568	                                                    content: nil,
569	                                                    speakableGroupName: groupName,
570	                                                    conversationIdentifier: roomProxy.id,
571	                                                    serviceName: nil,
572	                                                    sender: nil,
573	                                                    attachments: nil)
574	        
575	        let avatarURL: URL? = switch roomProxy.details.avatar {
576	        case .room(_, _, let avatarURL),
577	             .space(_, _, let avatarURL):
578	            avatarURL
579	        case .heroes(let userProfiles):
580	            userProfiles.first?.avatarURL
581	        case .tombstoned:
582	            nil
583	        }
584	        
585	        func addPlacehoder() {
586	            if let imageData = Avatars.generatePlaceholderAvatarImageData(name: displayName, id: roomProxy.id, size: .init(width: 100, height: 100)) {
587	                sendMessageIntent.setImage(INImage(imageData: imageData), forParameterNamed: \.speakableGroupName)
588	            }
589	        }
590	        
591	        if let avatarURL, let mediaSource = try? MediaSourceProxy(url: avatarURL, mimeType: nil) {
592	            if case let .success(avatarData) = await mediaProvider.loadThumbnailForSource(source: mediaSource, size: .init(width: 100, height: 100)) {
593	                sendMessageIntent.setImage(INImage(imageData: avatarData), forParameterNamed: \.speakableGroupName)
594	            } else {
595	                addPlacehoder()
596	            }
597	        } else {
598	            addPlacehoder()
599	        }
600	        
601	        let interaction = INInteraction(intent: sendMessageIntent, response: nil)
602	        
603	        do {
